<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('reports.export');$from=(string)($_GET['from']??date('Y-m-d',strtotime('-30 days')));$to=(string)($_GET['to']??date('Y-m-d'));header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="registration-report-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Registrations','Verified']);$q=db()->prepare('SELECT DATE(registration_at) day,COUNT(*) registrations,SUM(verification_status="verified") verified FROM drivers WHERE DATE(registration_at) BETWEEN ? AND ? GROUP BY DATE(registration_at) ORDER BY day');$q->execute([$from,$to]);foreach($q as $r)fputcsv($out,$r);fclose($out);exit;
